    yield from update_ui(chatbot=chatbot, history=history) # 刷新界面
    logger.info('Establishing knowledge archive ...')
    with ProxyNetworkActivate('Download_LLM'):    # 临时地激活代理网络
        kai = knowledge_archive_interface()
